class Solution:
    def minDifference(self, nums):
        n = len(nums)
        max_fixed = 0
        boundaries = []
        for i in range(n-1):
            a, b = nums[i], nums[i+1]
            if a != -1 and b != -1:
                max_fixed = max(max_fixed, abs(a-b))
            elif a == -1 and b == -1:
                continue
            else:
                if a == -1:
                    boundaries.append(b)
                else:
                    boundaries.append(a)
        if not boundaries:
            return 0 if all(x == -1 for x in nums) else max_fixed
        lo, hi = min(boundaries), max(boundaries)
        candidate = (hi - lo + 1) // 2
        return max(max_fixed, candidate)
